CGAL::Random rng(static_cast<unsigned int>(std::time(nullptr)));
int inside = 0;
for (int i = 0; i < numberOfChecks; ++i) {
    double x = 2.0 * rng.get_double() - 1.0;
    double y = 2.0 * rng.get_double() - 1.0;
    double z = 2.0 * rng.get_double() - 1.0;
    Point3d dir(x, y, z);
    if (dir == CGAL::ORIGIN) continue;
    Ray3d ray(p, dir);
    std::vector<Ray_intersection> intersections;
    tree.all_intersections(ray, std::back_inserter(intersections));
    int crossings = 0;
    for (const auto& it : intersections) {
        if (const Point3d* pt = std::get_if<Point3d>(&it->first)) {
            crossings++;
        } else if (const Segment3d* seg = std::get_if<Segment3d>(&it->first)) {
            crossings++;
        }
    }
    if (crossings % 2 == 1) inside++;
}
return inside > numberOfChecks / 2;
// END_CODE

